package ama.storage;
import ama.transcript.*;import ama.config.*;import ama.config.json.*;import ama.model.*;import ama.canonical.*;import ama.contract.MinutesContracts.*;import java.util.*;import java.nio.file.*;import java.io.*;import static ama.config.WireValues.*;import static org.junit.jupiter.api.Assertions.*;
/** Real completed candidate and immutable structural exclusions; no current pointer or Task10 adoption. */
class Task09PinnedRenderIT extends Task09GenerationRichIT {
 @Override void afterCandidate(Map<String,Object> candidate,JdbcMinutesFactsReader.Snapshot captured)throws Exception{
  Class<?> renderer=assertDoesNotThrow(()->Class.forName("ama.transcript.ControlledMinutesRenderer"));var root=j.queryForMap("SELECT * FROM meeting WHERE id=?",meeting);var first=draft(captured,(String)candidate.get("element_set_id"),(String)root.get("exclusion_revision_id"));phase("bind-pinned");var binding=bind(captured,first);phase("render-pinned");var payload=render(renderer,captured,first,binding);var values=fields(payload,"protocolVersion","modelIdentity","parameters","instructionText","inputManifest","transcript","template","pinnedElements","exclusions");var pinned=fields(values.get("pinnedElements"),"mode","rows");assertEquals("PINNED",text(pinned.get("mode")));assertEquals(11,array(pinned.get("rows")).size());
  phase("install-structural-exclusion");String locator=j.queryForObject("SELECT s.locator_id FROM sensitive_detection_source s JOIN sensitive_detection d ON d.id=s.detection_id WHERE d.set_id=? ORDER BY d.id LIMIT 1",String.class,candidate.get("element_set_id"));String exclusion=UUID.randomUUID().toString();new ama.db.TransactionRunner(source).required(()->{var access=app.getBean(ama.meeting.JdbcMeetingAccess.class);access.require(access.lock(actor(),meeting),ama.access.MeetingAccess.Action.EDIT);long revision=j.queryForObject("SELECT COALESCE(MAX(revision),0)+1 FROM exclusion_revision WHERE meeting_id=?",Long.class,meeting);assertEquals(1,j.update("INSERT INTO exclusion_revision(id,meeting_id,revision,created_at) VALUES (?,?,?,UTC_TIMESTAMP(6))",exclusion,meeting,revision));for(var kind:SensitiveKind.values())assertEquals(1,j.update("INSERT INTO sensitive_exclusion(revision_id,locator_id,category,reason) VALUES (?,?,?,?)",exclusion,locator,kind.name(),"structural exclusion "+kind.name()));return null;});
  var authority=ama.api.Task09RuntimeProbe.components(app).authority();var reader=new JdbcMinutesFactsReader(authority,this::snapshot,pin,new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,256));phase("read-structural-selection");var selected=(JdbcMinutesFactsReader.Snapshot)JdbcMinutesFactsReader.class.getMethod("readReuseSources",ama.contract.IdentityContracts.Actor.class,String.class,String.class,String.class).invoke(reader,actor(),meeting,candidate.get("id"),exclusion);assertEquals(2,selected.facts().rows().stream().filter(row->row.table()==Table.SENSITIVE_EXCLUSION&&row.string("revision_id").equals(exclusion)).count());
  var next=draft(selected,(String)candidate.get("element_set_id"),exclusion);phase("bind-excluded");var filtered=bind(selected,next);phase("render-excluded");var filteredPayload=render(renderer,selected,next,filtered);var f=fields(filteredPayload,"protocolVersion","modelIdentity","parameters","instructionText","inputManifest","transcript","template","pinnedElements","exclusions");assertEquals(2,array(fields(f.get("exclusions"),"revisionId","entries").get("entries")).size());assertEquals(array(values.get("transcript")).size()-1,array(f.get("transcript")).size());assertEquals(0,array(fields(f.get("pinnedElements"),"mode","rows").get("rows")).size());var excluded=fields(array(fields(f.get("exclusions"),"revisionId","entries").get("entries")).getFirst(),"sourceId","locatorId","category","reasonHash");String alias=text(excluded.get("sourceId"));assertTrue(array(f.get("transcript")).stream().noneMatch(v->text(fields(v,"sourceId","segmentId","body","marks").get("sourceId")).equals(alias)));assertEquals(root,j.queryForMap("SELECT * FROM meeting WHERE id=?",meeting));
  phase("strict-output-with-excluded-evidence");String result=j.queryForObject("SELECT o.external_result_id FROM external_operation o JOIN external_execution e ON e.operation_id=o.id WHERE e.task_id=?",String.class,candidate.get("task_id"));var output=json.readTree(Files.readAllBytes(providerStore.resolve("results/"+result+".json")));((com.fasterxml.jackson.databind.node.ObjectNode)output).put("inputFingerprint",filtered.fingerprint());byte[] wire=json.writeValueAsBytes(output);var parsed=new ama.minutes.json.StrictMinutesJsonReader().read(new ByteArrayInputStream(wire),new ValidationContext(filtered.fingerprint(),filtered.fingerprint(),Scope.FULL,filtered.catalog()),filtered,()->false);var failure=assertThrows(java.lang.reflect.InvocationTargetException.class,()->renderer.getMethod("rejectExcludedEvidence",ConfigBindings.ValidatedGenerationBinding.class,ValidatedOutput.class).invoke(null,filtered,parsed));assertInstanceOf(Failure.class,failure.getCause());assertEquals(FailureCode.SOURCE_NOT_IN_INPUT,((Failure)failure.getCause()).code());
  phase("strict-directory-only");((com.fasterxml.jackson.databind.node.ObjectNode)output).set("evidence",json.createArrayNode());((com.fasterxml.jackson.databind.node.ObjectNode)output).put("body","");for(var category:Category.values())((com.fasterxml.jackson.databind.node.ObjectNode)output.get("elements")).set(category.name(),json.createArrayNode());var directories=new ama.minutes.json.StrictMinutesJsonReader().read(new ByteArrayInputStream(json.writeValueAsBytes(output)),new ValidationContext(filtered.fingerprint(),filtered.fingerprint(),Scope.FULL,filtered.catalog()),filtered,()->false);renderer.getMethod("rejectExcludedEvidence",ConfigBindings.ValidatedGenerationBinding.class,ValidatedOutput.class).invoke(null,filtered,directories);
  Files.writeString(receipt.resolve("actual-pinned-exclusion-render.json"),json.writeValueAsString(Map.of("candidate",candidate.get("id"),"exclusion",exclusion,"sourceLocator",locator,"labelCount",2,"physicalLocationCount",1,"originalPinnedRows",11,"filteredPinnedRows",0,"rootUnchanged",true,"sourceFirstOnly",true,"excludedEvidenceRejected",true)));
 }
 void phase(String step)throws Exception{Files.writeString(receipt.resolve("render-phases.txt"),step+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}
 GenerationDraft draft(JdbcMinutesFactsReader.Snapshot facts,String set,String exclusion){var root=facts.observation();return new GenerationDraft(UUID.randomUUID().toString(),meeting,(String)root.get("transcript_confirmation_id"),null,(String)root.get("template_revision_id"),exclusion,set,prompt.version(),model.version(),Scope.FULL,null);}
 ConfigBindings.ValidatedGenerationBinding bind(JdbcMinutesFactsReader.Snapshot facts,GenerationDraft draft){var archive=snapshot();var graph=new GraphBudget(new CanonicalBudget(16777216,32,1000000,2097152,250000),128,256,B.maxFactRows());var roots=new ama.minutes.contract.GenerationArchiveRefs(facts.facts(),archive.index(),new StrictProcessingManifestReader(),B,graph,()->false).draft(draft);return new ConfigBindings(new StrictConfigArchiveReader(),new StrictProcessingManifestReader()).computeGeneration(draft,facts.facts(),new Fence(4,4,0),archive.loadClosure(roots,B,0,()->false),graph,B,()->false);}
 CanonicalValue.ObjectValue render(Class<?> renderer,JdbcMinutesFactsReader.Snapshot facts,GenerationDraft draft,ConfigBindings.ValidatedGenerationBinding binding)throws Exception{return (CanonicalValue.ObjectValue)renderer.getMethod("render",List.class,GenerationDraft.class,ConfigBindings.ValidatedGenerationBinding.class).invoke(null,facts.facts().rows(),draft,binding);}
}
